                                       float* __restrict__ out,
                                       int B, int F, int strideF,
                                       int total_vecs,
                                       float eps) {
    int tid = threadIdx.x;
    int vec = tid >> 5;    // /32
    int lane = tid & 31;   // %32

    int g = (int)blockIdx.x * VEC_PER_BLOCK + vec;
    if (g >= total_vecs) return;

    int b = g / strideF;
    int inner = g - b * strideF;
    int base = (b * F) * strideF + inner;

    // load two features: lane and lane+32
    int f0 = lane;
    int f1 = lane + 32;

    float v0 = x[base + f0 * strideF];
    float v1 = x[base + f1 * strideF];

    float sumsq = v0 * v0 + v1 * v1;
    sumsq = warp_reduce_sum(sumsq);

    float inv;
    if (lane == 0) {
        float mean = sumsq * (1.0f / 64.0f);
        inv = rsqrtf(mean + eps);
